<style>
/* CRM Contracts — shared layout & component styles */
.contract-list-card,.contract-form-card,.contract-details-card{overflow:visible}
.contract-filter-bar{display:grid;grid-template-columns:minmax(190px,1.5fr) minmax(140px,1fr) minmax(190px,1fr) auto;gap:14px;align-items:end;margin-bottom:22px}
.contract-filter-bar>div{min-width:0}.contract-filter-bar label{display:block;margin-bottom:7px;font-size:12px;font-weight:600;color:#334155}.contract-filter-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.contract-filter-bar .form-control,.contract-form-card .form-control{box-sizing:border-box;width:100%;min-height:42px;padding:10px 12px;border:1px solid var(--border,#cbd5e1);border-radius:7px;background:#fff;color:var(--text-primary,#1e293b);font:inherit;font-size:13px}
.contract-filter-bar .form-control:focus,.contract-form-card .form-control:focus{outline:none;border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.10)}
.contract-table-scroll{overflow-x:auto;width:100%}.contract-list-table{width:100%;border-collapse:collapse;min-width:980px;border:1px solid #e2e8f0}.contract-list-table th{background:#f8fafc;color:#64748b;text-transform:uppercase;letter-spacing:.3px;font-size:10px;font-weight:700;white-space:nowrap;text-align:left;padding:13px 12px;border-bottom:1px solid #e2e8f0}.contract-list-table td{padding:13px 12px;font-size:12px;color:#334155;vertical-align:middle;border-bottom:1px solid #edf1f6}.contract-list-table tbody tr:hover{background:#fafcff}.contract-list-table th:last-child,.contract-list-table td:last-child{text-align:center}.contract-strong-link{color:#17284f;text-decoration:none;font-weight:700}.contract-strong-link:hover{color:#2563eb}.contract-empty{text-align:center;padding:30px!important;color:#64748b!important}.contract-table-footer{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-top:19px;color:#64748b;font-size:12px}
.contract-status{display:inline-flex;align-items:center;justify-content:center;padding:5px 9px;border-radius:6px;font-size:11px;font-weight:700;background:#f1f5f9;color:#475569}.contract-status.active{background:#dff5ed;color:#087f59}.contract-status.draft{background:#f1f5f9;color:#64748b}.contract-status.expired{background:#fff2d9;color:#976014}.contract-status.terminated{background:#ffe8e8;color:#bf3434}
.contract-table-actions{display:flex;justify-content:center;align-items:center;gap:6px;white-space:nowrap}.contract-icon-action{box-sizing:border-box;appearance:none;display:inline-flex;justify-content:center;align-items:center;flex:0 0 34px;width:34px;height:34px;margin:0;padding:0;line-height:1;vertical-align:middle;border:1px solid #dfe6ef;border-radius:7px;background:#fff;cursor:pointer;text-decoration:none}.contract-icon-action svg{display:block;flex:none;width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.contract-icon-action.view{color:#2563eb}.contract-icon-action.edit{color:#d97706}.contract-icon-action.delete{color:#dc2626}.contract-icon-action:hover{background:#f8fafc}
.contract-delete-modal[hidden]{display:none!important}.contract-delete-modal{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px}.contract-delete-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.56)}.contract-delete-dialog{position:relative;z-index:1;width:100%;max-width:410px;border-radius:14px;background:white;padding:27px;text-align:center;box-shadow:0 18px 60px rgba(0,0,0,.22)}.contract-delete-symbol{display:grid;place-items:center;width:50px;height:50px;margin:0 auto 12px;background:#fee2e2;border-radius:50%;font-size:23px;font-weight:700;color:#dc2626}.contract-delete-dialog h3{font-size:18px;margin:0 0 10px}.contract-delete-dialog p{font-size:13px;line-height:1.6;margin:0 0 7px}.contract-delete-dialog small{color:#64748b}.contract-delete-actions{display:flex;justify-content:center;gap:10px;margin-top:22px}.contract-danger-btn{background:#dc2626!important;color:white!important;border-color:#dc2626!important}
.contract-editor-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(285px,.75fr);gap:32px;align-items:start}.contract-editor-main{min-width:0}.contract-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.contract-form-card .form-group{display:flex;flex-direction:column;gap:8px;min-width:0}.contract-form-card .form-group label{font-size:13px;font-weight:600;color:#334155}.contract-form-section+.contract-form-section{border-top:1px solid #e2e8f0;margin-top:30px;padding-top:26px}.contract-section-title{margin-bottom:20px}.contract-section-title h4,.contract-details-section h4{margin:0 0 6px;font-size:15px;font-weight:700;color:#1e293b}.contract-section-title p{margin:0;font-size:13px;line-height:1.6;color:#64748b}.contract-asterisk,.contract-required b{color:#dc2626}.contract-required{font-size:12px;color:#64748b}.contract-hint{font-size:11px;line-height:1.5;color:#64748b}.contract-error{font-size:11px;color:#dc2626}.contract-auto-field{position:relative}.contract-auto-field input{padding-right:60px!important;background:#f8fafc!important}.contract-auto-field span{position:absolute;right:10px;top:50%;transform:translateY(-50%);padding:4px 7px;background:#dbeafe;color:#1d4ed8;border-radius:5px;font-size:10px;font-weight:700}.contract-form-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid #e2e8f0;margin-top:30px;padding-top:22px}
.contract-preview-panel{position:sticky;top:92px;min-width:0;height:fit-content;padding:24px;border:1px solid #e2e8f0;border-radius:10px;background:#f8fafc;box-sizing:border-box}.contract-preview-label{font-size:10px;letter-spacing:1.2px;font-weight:700;color:#64748b;margin-bottom:20px}.contract-preview-head{display:flex;align-items:center;gap:13px;min-width:0}.contract-preview-icon{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;border-radius:10px;background:#dbeafe;color:#1d4ed8;font-weight:700;font-size:17px}.contract-preview-head>div:last-child{min-width:0}.contract-preview-head h3{font-size:16px;font-weight:700;margin:0 0 5px;overflow-wrap:anywhere;color:#1e293b}.contract-preview-head span{font-size:11px;color:#64748b}.contract-preview-divider{height:1px;margin:21px 0;background:#e2e8f0}.contract-preview-row{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;padding:9px 0}.contract-preview-row>span{flex-shrink:0;color:#64748b;font-size:11px}.contract-preview-row strong{max-width:65%;font-size:12px;text-align:right;overflow-wrap:anywhere;color:#334155;font-weight:600}.contract-preview-status{padding:4px 8px;border-radius:6px;background:#f1f5f9;color:#64748b!important;font-size:10px!important}.contract-preview-status.active{background:#dcfce7;color:#15803d!important}.contract-preview-status.expired{background:#fff2d9;color:#976014!important}.contract-preview-status.terminated{background:#fee2e2;color:#b91c1c!important}.contract-preview-note{margin-top:20px;padding:13px 14px;border:1px solid #e2e8f0;border-radius:7px;background:white}.contract-preview-note strong{display:block;margin-bottom:5px;color:#334155;font-size:11px}.contract-preview-note p{margin:0;color:#64748b;font-size:10px;line-height:1.6}
.contract-details-section+.contract-details-section{border-top:1px solid #e2e8f0;margin-top:27px;padding-top:24px}.contract-detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:17px}.contract-detail-grid>div{background:#f8fafc;border:1px solid #e8edf4;border-radius:8px;padding:13px 15px;min-width:0}.contract-detail-grid span{display:block;font-size:11px;color:#64748b;margin-bottom:8px}.contract-detail-grid strong{font-size:13px;font-weight:600;color:#17284f;overflow-wrap:anywhere}.contract-document-box{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:17px;padding:18px;border-radius:8px;border:1px solid #e8edf4;background:#f8fafc}.contract-document-box strong{font-size:13px;color:#17284f}.contract-document-box p{margin:5px 0 0;font-size:12px;color:#64748b}
@media(max-width:1050px){.contract-filter-bar{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:900px){.contract-editor-layout{grid-template-columns:1fr}.contract-preview-panel{position:static;order:-1}}@media(max-width:650px){.contract-filter-bar,.contract-form-grid,.contract-detail-grid{grid-template-columns:1fr}.contract-filter-actions{justify-content:flex-start}.contract-document-box{flex-direction:column;align-items:flex-start}.contract-form-actions{flex-wrap:wrap}}
</style>